RELEASE = '4f1b9c52da789dbad9333e8f62c7b27ff48304bd'

COMMIT = '84400ca74868ada12900f8756e2ba5ddd2f41082'

PROTOCOL_HASH = 'f9e01319fac638a35a22af8ed3a10517c82233dae9b5c46172f30ca22d503e1a'

